 18	
 19	    public ReservationService(
 20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 21	        this.rooms = rooms;
 22	        this.store = store;
 23	        this.priceCalculator = priceCalculator;
 24	        this.emailSender = emailSender;
 25	    }
 26	
 27	    public synchronized Reservation create(NewReservation request) {
 28	        if (!request.checkOut().isAfter(request.checkIn())) {
 29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 30	        }
 31	        if (request.guests() < 1) {
 32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 33	        }
 34	        Room room = rooms.find(request.roomNumber())
 35	                .orElseThrow(() -> new HotelException(
 36	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 37	        if (request.guests() > room.capacity()) {
 38	            throw new HotelException(
 39	                    ErrorCode.CAPACITY_EXCEEDED,
 40	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 41	        }
 42	        request.ratePlan().pricing().validate(request, room);
 43	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 44	            throw new HotelException(
 45	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 46	        }
 47	        Price price = priceCalculator.calculate(
 48	                room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
 49	        return store.add(request, price);
 50	    }
 51	
 52	    public Reservation find(long reservationId) {
 53	        return store.find(reservationId)
 54	                .orElseThrow(() -> new HotelException(
 55	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 56	    }
 57	
 58	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 59	    public synchronized Reservation confirm(long reservationId) {
 60	        Reservation reservation = find(reservationId);
 61	        if (reservation.status() != ReservationStatus.PENDING) {
 62	            throw notAllowed(reservation, "confirm");
 63	        }
 64	        reservation.confirmPayment();
 65	        store.update(reservation);
 66	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
 67	        emailSender.send(
 68	                reservation.guest().email(),
 69	                "Reserva confirmada - " + HOTEL_NAME,
 70	                confirmationEmailBody(reservation, receipt));
