  2	
  3	import com.fasterxml.jackson.databind.ObjectMapper;
  4	import com.fasterxml.jackson.databind.SerializationFeature;
  5	import com.fasterxml.jackson.databind.json.JsonMapper;
  6	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  7	import hotel.messages.SentMessages;
  8	import hotel.reports.OccupancyReport;
  9	import hotel.reports.RevenueReport;
 10	import hotel.reservations.ErrorCode;
 11	import hotel.reservations.Guest;
 12	import hotel.reservations.HotelException;
 13	import hotel.reservations.NewReservation;
 14	import hotel.reservations.ReservationService;
 15	import hotel.rooms.Rooms;
 16	import io.javalin.Javalin;
 17	import io.javalin.http.Context;
 18	import io.javalin.json.JavalinJackson;
 19	import java.time.LocalDate;
 20	import java.time.YearMonth;
 21	import java.time.format.DateTimeParseException;
 22	
 23	/** The HTTP API the inn's website and front desk call. */
 24	public final class HttpApi {
 25	
 26	    private final Javalin server;
 27	    private final Rooms rooms;
 28	    private final ReservationService reservations;
 29	    private final SentMessages sentMessages;
 30	    private final OccupancyReport occupancyReport;
 31	    private final RevenueReport revenueReport;
 32	
 33	    public HttpApi(
 34	            Rooms rooms,
 35	            ReservationService reservations,
 36	            SentMessages sentMessages,
 37	            OccupancyReport occupancyReport,
 38	            RevenueReport revenueReport) {
 39	        this.rooms = rooms;
 40	        this.reservations = reservations;
 41	        this.sentMessages = sentMessages;
 42	        this.occupancyReport = occupancyReport;
 43	        this.revenueReport = revenueReport;
 44	
 45	        ObjectMapper jsonMapper = JsonMapper.builder()
 46	                .addModule(new JavaTimeModule())
 47	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
 48	                .build();
 49	        this.server = Javalin.create(config -> {
 50	            config.showJavalinBanner = false;
 51	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
 52	        });
 53	        registerRoutes();
 54	        registerErrorHandling();
 55	    }
 56	
 57	    public Javalin server() {
 58	        return server;
 59	    }
 60	
 61	    private void registerRoutes() {
 62	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
 63	
 64	        server.post("/reservations", ctx -> {
 65	            NewReservation request = readNewReservation(ctx);
 66	            ctx.status(201).json(new ReservationResponse(reservations.create(request)));
 67	        });
 68	        server.get("/reservations/{id}", ctx ->
 69	                ctx.json(new ReservationResponse(reservations.find(reservationId(ctx)))));
 70	        server.post("/reservations/{id}/confirmation", ctx ->
 71	                ctx.json(new ReservationResponse(reservations.confirm(reservationId(ctx)))));
 72	        server.post("/reservations/{id}/cancellation", ctx ->
 73	                ctx.json(new ReservationResponse(reservations.cancel(reservationId(ctx)))));
 74	        server.post("/reservations/{id}/check-in", ctx ->
 75	                ctx.json(new ReservationResponse(reservations.checkIn(reservationId(ctx)))));
 76	        server.post("/reservations/{id}/check-out", ctx ->
 77	                ctx.json(reservations.checkOut(reservationId(ctx))));
 78	        server.get("/reservations/{id}/document", ctx ->
 79	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
 80	
 81	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
 82	
 83	        server.get("/reports/occupancy", ctx -> {
 84	            LocalDate night = readDate(ctx);
 85	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
 86	        });
 87	        server.get("/reports/revenue", ctx -> {
 88	            YearMonth month = readMonth(ctx);
 89	            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
 90	        });
 91	    }
 92	
 93	    private void registerErrorHandling() {
 94	        server.exception(HotelException.class, (exception, ctx) -> {
 95	            ctx.status(httpStatus(exception.errorCode()));
 96	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
 97	        });
 98	    }
 99	
100	    private static int httpStatus(ErrorCode errorCode) {
101	        return switch (errorCode) {
102	            case INVALID_REQUEST -> 400;
103	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
104	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
105	            case CAPACITY_EXCEEDED -> 422;
106	        };
107	    }
108	
109	    private static NewReservation readNewReservation(Context ctx) {
110	        CreateReservationRequest body;
111	        try {
112	            body = ctx.bodyAsClass(CreateReservationRequest.class);
113	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
114	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
115	        }
116	        if (body == null
117	                || body.roomNumber() == null
118	                || isBlank(body.guestName())
119	                || isBlank(body.guestEmail())
120	                || isBlank(body.guestCpf())
121	                || body.checkIn() == null
122	                || body.checkOut() == null
123	                || body.guests() == null
124	                || body.ratePlan() == null) {
125	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
126	        }
127	        Guest guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
128	        return new NewReservation(
129	                body.roomNumber(),
130	                guest,
131	                body.checkIn(),
132	                body.checkOut(),
133	                body.guests(),
134	                body.ratePlan(),
135	                body.companyCode());
136	    }
137	
138	    private static long reservationId(Context ctx) {
139	        String id = ctx.pathParam("id");
140	        try {
141	            return Long.parseLong(id);
142	        } catch (NumberFormatException notANumber) {
143	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
144	        }
145	    }
146	
147	    private static LocalDate readDate(Context ctx) {
148	        String date = requiredQueryParam(ctx, "date");
149	        try {
150	            return LocalDate.parse(date);
151	        } catch (DateTimeParseException badDate) {
152	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
153	        }
154	    }
155	
156	    private static YearMonth readMonth(Context ctx) {
157	        String month = requiredQueryParam(ctx, "month");
158	        try {
159	            return YearMonth.parse(month);
160	        } catch (DateTimeParseException badMonth) {
161	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
162	        }
163	    }
164	
165	    private static String requiredQueryParam(Context ctx, String name) {
166	        String value = ctx.queryParam(name);
167	        if (value == null) {
168	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
169	        }
170	        return value;
171	    }
172	
173	    private static boolean isBlank(String text) {
174	        return text == null || text.isBlank();
175	    }
176	}
177	package hotel;
178	
179	import hotel.messages.EmailSender;
180	import hotel.messages.SentMessages;
181	import hotel.reports.OccupancyReport;
182	import hotel.reports.RevenueReport;
183	import hotel.reservations.PriceCalculator;
184	import hotel.reservations.ReservationService;
185	import hotel.reservations.ReservationStore;
186	import hotel.rooms.Rooms;
187	import hotel.web.HttpApi;
188	import io.javalin.Javalin;
189	import javax.sql.DataSource;
190	
191	/** Puts the inn's pieces together and runs the HTTP server. */
192	public final class Hotel {
193	
194	    private final Javalin server;
195	
196	    public Hotel(DataSource dataSource) {
197	        Rooms rooms = new Rooms(dataSource);
198	        ReservationStore store = new ReservationStore(dataSource);
199	        SentMessages sentMessages = new SentMessages(dataSource);
200	        ReservationService reservations =
201	                new ReservationService(rooms, store, new PriceCalculator(), new EmailSender(sentMessages));
202	        HttpApi api = new HttpApi(
203	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
204	        this.server = api.server();
205	    }
206	
207	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
208	    public int start(int port) {
209	        server.start(port);
210	        return server.port();
211	    }
212	
213	    public void stop() {
214	        server.stop();
215	    }
216	
217	    public static void main(String[] args) {
218	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
219	        Database database = new Database(System.getenv());
220	        new Hotel(database.dataSource()).start(port);
221	    }
222	}

