116	package hotel.reservations;
117	
118	import java.math.BigDecimal;
119	import java.sql.Connection;
120	import java.sql.Date;
121	import java.sql.PreparedStatement;
122	import java.sql.ResultSet;
123	import java.sql.SQLException;
124	import java.time.LocalDate;
125	import java.util.ArrayList;
126	import java.util.List;
127	import java.util.Optional;
128	import javax.sql.DataSource;
129	
130	/** Keeps the reservations in the database. */
131	public final class ReservationStore {
132	
133	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
134	            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
135	    /** PostgreSQL's code for a broken exclusion constraint: here, the room was already booked on one of the nights. */
136	    private static final String EXCLUSION_VIOLATION = "23P01";
137	
138	    private final DataSource dataSource;
139	
140	    public ReservationStore(DataSource dataSource) {
141	        this.dataSource = dataSource;
142	    }
143	
144	    /** Saves a new reservation; the database numbers it. */
145	    Reservation add(NewReservation request, Price price) {
146	        String insert = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, "
147	                + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid) "
148	                + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id";
149	        try (Connection connection = dataSource.getConnection();
150	                PreparedStatement statement = connection.prepareStatement(insert)) {
151	            statement.setInt(1, request.roomNumber());
152	            statement.setString(2, request.guest().name());
153	            statement.setString(3, request.guest().email());
154	            statement.setString(4, request.guest().cpf());
155	            statement.setDate(5, Date.valueOf(request.checkIn()));
156	            statement.setDate(6, Date.valueOf(request.checkOut()));
157	            statement.setInt(7, request.guests());
158	            statement.setString(8, request.ratePlan().name());
159	            statement.setInt(9, price.nights());
160	            statement.setBigDecimal(10, price.subtotal());
161	            statement.setBigDecimal(11, price.discount());
162	            statement.setBigDecimal(12, price.total());
163	            statement.setString(13, ReservationStatus.PENDING.name());
164	            statement.setBigDecimal(14, PriceCalculator.cents(BigDecimal.ZERO));
165	            try (ResultSet generated = statement.executeQuery()) {
166	                generated.next();
167	                return new Reservation(generated.getLong("id"), request, price);
168	            }
169	        } catch (SQLException failure) {
170	            if (EXCLUSION_VIOLATION.equals(failure.getSQLState())) {
171	                throw new HotelException(ErrorCode.ROOM_UNAVAILABLE,
172	                        "room " + request.roomNumber() + " is taken on some of those nights");
173	            }
174	            throw new IllegalStateException("could not save the reservation", failure);
175	        }
176	    }
177	
178	    /** Saves what changes in a reservation's life: the status, what was paid and what went back. */
179	    void update(Reservation reservation) {
180	        try (Connection connection = dataSource.getConnection();
181	                PreparedStatement statement = connection.prepareStatement(
182	                        "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
183	            statement.setString(1, reservation.status().name());
184	            statement.setBigDecimal(2, reservation.amountPaid());
185	            statement.setBigDecimal(3, reservation.refund());
186	            statement.setLong(4, reservation.id());
187	            statement.executeUpdate();
188	        } catch (SQLException failure) {
189	            throw new IllegalStateException("could not save reservation " + reservation.id(), failure);
190	        }
191	    }
192	
193	    /** Whether a reservation that was not cancelled holds the room on any of the nights. */
194	    boolean isRoomTaken(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
195	        try (Connection connection = dataSource.getConnection();
196	                PreparedStatement select = connection.prepareStatement(
197	                        "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
198	                                + "AND check_in < ? AND ? < check_out")) {
199	            select.setInt(1, roomNumber);
200	            select.setDate(2, Date.valueOf(checkOut));
201	            select.setDate(3, Date.valueOf(checkIn));
202	            try (ResultSet rows = select.executeQuery()) {
203	                return rows.next();
204	            }
205	        } catch (SQLException failure) {
206	            throw new IllegalStateException("could not check room " + roomNumber, failure);
207	        }
208	    }
209	
210	    public Optional<Reservation> find(long id) {
211	        try (Connection connection = dataSource.getConnection();
212	                PreparedStatement select = connection.prepareStatement(
213	                        "SELECT " + COLUMNS + " FROM reservations WHERE id = ?")) {
214	            select.setLong(1, id);
215	            try (ResultSet rows = select.executeQuery()) {
216	                return rows.next() ? Optional.of(read(rows)) : Optional.empty();
217	            }
218	        } catch (SQLException failure) {
219	            throw new IllegalStateException("could not read reservation " + id, failure);
220	        }
221	    }
222	
223	    public List<Reservation> all() {
224	        try (Connection connection = dataSource.getConnection();
225	                PreparedStatement select = connection.prepareStatement(
226	                        "SELECT " + COLUMNS + " FROM reservations ORDER BY id");
227	                ResultSet rows = select.executeQuery()) {
228	            List<Reservation> reservations = new ArrayList<>();
229	            while (rows.next()) {
230	                reservations.add(read(rows));
231	            }
232	            return reservations;
233	        } catch (SQLException failure) {
234	            throw new IllegalStateException("could not read the reservations", failure);
235	        }
236	    }
237	
238	    private static Reservation read(ResultSet row) throws SQLException {
239	        Guest guest = new Guest(row.getString("guest_name"), row.getString("guest_email"), row.getString("guest_cpf"));
240	        NewReservation request = new NewReservation(
241	                row.getInt("room_number"),
242	                guest,
243	                row.getDate("check_in").toLocalDate(),
244	                row.getDate("check_out").toLocalDate(),
245	                row.getInt("guests"),
246	                RatePlan.valueOf(row.getString("rate_plan")),
247	                null);
248	        Price price = new Price(
249	                row.getInt("nights"), row.getBigDecimal("subtotal"), row.getBigDecimal("discount"),
250	                row.getBigDecimal("total"));
251	        return new Reservation(
252	                row.getLong("id"),
253	                request,
254	                price,
255	                ReservationStatus.valueOf(row.getString("status")),
256	                row.getBigDecimal("amount_paid"),
257	                row.getBigDecimal("refund"));
258	    }
259	}

